ruleToc.chapterList:
@js:
(function(){
  var d = null;
  if (typeof result === 'string') { try { d = JSON.parse(result); } catch(e){} }
  else { d = result; }
  if (!d) return [];
  var data = d.data || {};
  var vs = data.videos || [];
  var pid = '';
  try { var m = String(baseUrl||'').match(/pid=(\d+)/); if (m) pid = m[1]; } catch(e){}
  if (!pid) { try { var m2 = String(book.bookUrl||'').match(/pid=(\d+)/); if (m2) pid = m2[1]; } catch(e){} }
  var out = [];
  var seen = {};
  for (var i=0;i<vs.length;i++){
    var v = vs[i] || {};
    var seq = v.seq || (i+1);
    var u = v.videoUrl || '';
    if (!u) continue;
    if (seen[seq]) continue;
    seen[seq] = 1;
    out.push({
      name: '第' + seq + '集',
      url: 'https://yy-playlet.yy.com/playlet/video-list?pid=' + pid + '&direct=1&pageSize=30&recommend=false&seq=' + seq,
      isVolume: false
    });
  }
  return out;
})()
